import express from 'express'
import { createDb } from './db'
import { config } from './config'

// Anonbook routes
import { signupRouter } from './routes/anonbook-signup'
import { attestRouter } from './routes/anonbook-attest'
import { postRouter } from './routes/anonbook-post'
import { feedRouter } from './routes/anonbook-feed'
import { devRouter } from './routes/dev'

require('dotenv').config()

const app = express()

app.use(express.json())

app.get<{}, any>('/', (req, res) => {
    res.json({
        message: 'Welcome to Anonbook API!',
    })
})
app.use('*', (req, res, next) => {
    res.set('access-control-allow-origin', '*')
    res.set('access-control-allow-headers', '*')
    next()
})

// Anonbook Karma Bridge routes
const db = createDb(config.dbPath)
app.use('/api', signupRouter(db))
app.use('/api', attestRouter(db))
app.use('/api', postRouter(db))
app.use('/api', feedRouter(db))

// Dev-only routes (epoch advancement for testing)
if (process.env.NODE_ENV !== 'production') {
    app.use('/api', devRouter())
}

export default app

import { Router } from 'express'
import { ethers } from 'ethers'
import { config } from '../config'

export function devRouter(): Router {
    const router = Router()

    router.post('/dev/advance-epoch', async (req, res) => {
        try {
            const provider = new ethers.providers.JsonRpcProvider(
                config.provider
            )
            const unirep = new ethers.Contract(
                config.unirepAddress,
                [
                    'function attesterEpochLength(uint160 attesterId) public view returns (uint256)',
                ],
                provider
            )
            const epochLength = await unirep.attesterEpochLength(
                config.karmaBridgeAddress
            )
            await provider.send('evm_increaseTime', [Number(epochLength)])
            await provider.send('evm_mine', [])

            res.json({ success: true, advancedSeconds: Number(epochLength) })
        } catch (err: any) {
            console.error('[dev/advance-epoch] Error:', err)
            res.status(500).json({ success: false, error: err.message })
        }
    })

    return router
}

